using HospitalManagement.Web.Models; using HospitalManagement.Web.Services; using Microsoft.AspNetCore.Mvc;
namespace HospitalManagement.Web.Controllers;
public class PrescriptionsController:Controller{private readonly HospitalApiService api;public PrescriptionsController(HospitalApiService api)=>this.api=api;
[HttpGet]public IActionResult Index()=>View();[HttpGet]public IActionResult Create()=>View(new PrescriptionViewModel());[HttpGet]public IActionResult Edit(int id)=>View("Create",new PrescriptionViewModel{Id=id});[HttpGet]public async Task<IActionResult>Get(int id){var r=await api.GetPrescriptionAsync(id);return r.Ok?Json(new{success=true,data=r.Data}):NotFound(new{message=r.Message});}
[HttpPost][IgnoreAntiforgeryToken]public async Task<IActionResult>List([FromBody]SearchRequest request){var r=await api.PrescriptionsAsync(request.Search);return r.Ok?Json(new{success=true,data=r.Data}):StatusCode(502,new{message=r.Message});}
[HttpPost][IgnoreAntiforgeryToken]public async Task<IActionResult>Save([FromBody]System.Text.Json.JsonElement body){var id=body.TryGetProperty("id",out var idProp)?idProp.GetInt32():0;var payload=body.Clone();var r=id==0?await api.CreatePrescriptionAsync(payload):await api.UpdatePrescriptionAsync(id,payload);return r.Ok?Json(new{success=true,message=id==0?"Prescription created successfully.":"Prescription updated successfully.",data=r.Data}):BadRequest(new{message=r.Message});}
[HttpPost][IgnoreAntiforgeryToken]public async Task<IActionResult>Delete([FromBody]IdRequest request){var r=await api.DeletePrescriptionAsync(request.Id);return r.Ok?Json(new{success=true,message="Prescription deleted successfully."}):BadRequest(new{message=r.Message});}}
